# ── 공통 도우미: 이후 회사들은 E()로 짧게 적는다 ──
NV = "https://n.news.naver.com/mnews/article/"
ASOF = "2026-11-05"


def E(code, take, items, tone=None, title=None, latest=None):
    d = dict(asof=ASOF, take=take,
             items=[(a, b, (u if u.startswith("http") else NV + u), s, r, i) for a, b, u, s, r, i in items])
    if tone: d["tone"] = tone
    if title: d["title"] = title
    if latest: d["latest"] = latest
    N[code] = d


def L(rev, op, ni, note, period="2026Q3"):
    return dict(period=period, rev=rev, op=op, ni=ni, note=note)


